#!/usr/bin/env -S deno run --allow-read

// Deterministic audit for item economy completeness. It distinguishes
// authored values from explicit, documented derivations so a default cannot
// silently masquerade as design intent.

import "../../../../src/content/items/index.js";
import { installContent } from "../../../../src/content/install.js";
import { listCatalogItems } from "../../../../src/rules/data/itemCatalog.js";

installContent();

export function parseArgs(argv) {
  const opts = { format: "summary", issues: false, limit: 0 };
  for (let i = 0; i < argv.length; i++) {
    const arg = String(argv[i] || "");
    if (arg === "--format" && argv[i + 1]) opts.format = String(argv[++i]);
    else if (arg === "--issues") opts.issues = true;
    else if (arg === "--limit" && argv[i + 1]) opts.limit = Math.max(0, Number(argv[++i]) | 0);
    else if (arg === "--help" || arg === "-h") opts.help = true;
  }
  return opts;
}

function positiveNumber(value) {
  return Number.isFinite(Number(value)) && Number(value) > 0;
}

export function auditItemEconomy(items = listCatalogItems()) {
  return [...items].map((item) => {
    const economy = item.economy && typeof item.economy === "object" ? item.economy : {};
    const legacyValueSource = positiveNumber(item.value) ? "legacy-authored" : "unknown";
    const legacyWeightSource = positiveNumber(item.weight) ? "legacy-authored" : "unknown";
    const issues = [];
    if (!positiveNumber(item.value)) issues.push("missing-effective-value");
    if (!positiveNumber(item.weight)) issues.push("missing-effective-weight");
    const valueSource = String(economy.valueSource || legacyValueSource);
    const weightSource = String(economy.weightSource || legacyWeightSource);
    if (valueSource !== "authored" && valueSource !== "legacy-authored") issues.push(`value:${valueSource}`);
    if (weightSource !== "authored" && weightSource !== "legacy-authored") issues.push(`weight:${weightSource}`);
    return {
      id: String(item.id || ""),
      name: String(item.name || ""),
      catalogKind: String(item.catalogKind || ""),
      type: String(item.type || ""),
      value: Number(item.value || 0),
      weight: Number(item.weight || 0),
      valueSource,
      weightSource,
      issues,
    };
  }).sort((a, b) => a.id.localeCompare(b.id));
}

export function filterItems(items, opts) {
  return items.filter((item) => !opts.issues || item.issues.length > 0);
}

function formatCsv(items) {
  const quote = (value) => `"${String(value).replaceAll('"', '""')}"`;
  const rows = ["id,name,catalogKind,type,value,weight,valueSource,weightSource,issues"];
  for (const item of items) rows.push([
    item.id, item.name, item.catalogKind, item.type, item.value, item.weight,
    item.valueSource, item.weightSource, item.issues.join("|"),
  ].map(quote).join(","));
  return rows.join("\n");
}

export function formatReport(items, format = "summary") {
  if (format === "json") return JSON.stringify(items, null, 2);
  if (format === "csv") return formatCsv(items);
  const derivedValues = items.filter((item) => item.valueSource === "derived-stat-model").length;
  const derivedWeights = items.filter((item) => item.weightSource === "derived-type-model").length;
  const missing = items.filter((item) => item.issues.some((issue) => issue.startsWith("missing-effective"))).length;
  const lines = [
    `items: ${items.length}`,
    `effective gaps: ${missing}`,
    `derived values: ${derivedValues}`,
    `derived weights: ${derivedWeights}`,
  ];
  for (const item of items) {
    if (item.issues.length === 0) continue;
    lines.push(`${item.id} value=${item.value}(${item.valueSource}) weight=${item.weight}(${item.weightSource}) [${item.issues.join(";")}]`);
  }
  return lines.join("\n");
}

if (import.meta.main) {
  const opts = parseArgs(Deno.args);
  if (opts.help) console.log("Usage: deno run --allow-read .agents/skills/agent-tools/scripts/item-economy-audit.mjs [--issues] [--format summary|csv|json] [--limit N]");
  else {
    const filtered = filterItems(auditItemEconomy(), opts);
    const limited = opts.limit > 0 ? filtered.slice(0, opts.limit) : filtered;
    console.log(formatReport(limited, opts.format));
  }
}

